contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount, uint minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cEthBefore = address(c).balance;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cEthAfter = address(c).balance;

        assert(! (balBefore >= minSum && balBefore >= collectAmount)
            || (!reverted && balAfter == balBefore - collectAmount && cEthAfter == cEthBefore - collectAmount)
            || (reverted && balAfter == balBefore && cEthAfter == cEthBefore));
    }

    receive() external payable {}
}

